/* FIPS 202 SHAKE. Output from OpenSSL (Node crypto).
 * shake: valid 3, invalid 0, acceptable 0, refuse 0. Fields: msg, out.
 * Regenerated by config/crypto-vectors.js.
 */
#ifndef SHAKE_H
#define SHAKE_H
#include <stdint.h>
typedef struct { uint32_t id; uint8_t result; uint32_t off; uint16_t n[2]; } shake_vec_t;
static const uint8_t shake_blob[] = {
	0x61, 0x62, 0x63, 0x58, 0x81, 0x09, 0x2d, 0xd8, 0x18, 0xbf, 0x5c, 0xf8,
	0xa3, 0xdd, 0xb7, 0x93, 0xfb, 0xcb, 0xa7, 0x61, 0x62, 0x63, 0x48, 0x33,
	0x66, 0x60, 0x13, 0x60, 0xa8, 0x77, 0x1c, 0x68, 0x63, 0x08, 0x0c, 0xc4,
	0x11, 0x4d, 0x8d, 0xb4, 0x45, 0x30, 0xf8, 0xf1, 0xe1, 0xee, 0x4f, 0x94,
	0xea, 0x37, 0xe7, 0x8b, 0x57, 0x39, 0x7f, 0x9c, 0x2b, 0xa4, 0xe8, 0x8f,
	0x82, 0x7d, 0x61, 0x60, 0x45, 0x50, 0x76, 0x05, 0x85, 0x3e,
};
static const shake_vec_t shake_vec[] = {
	{ 1, 1, 0, { 3, 16 } },
	{ 2, 1, 19, { 3, 32 } },
	{ 3, 1, 54, { 0, 16 } },
};
#define SHAKE_COUNT ((unsigned)(sizeof(shake_vec) / sizeof(shake_vec[0])))
static const uint8_t *shake_at(unsigned i, unsigned field) {
	const uint8_t *p = shake_blob + shake_vec[i].off;
	unsigned f;

	for(f = 0; f < field; f++)
		p += shake_vec[i].n[f];
	return(p);
}
#endif
